    fn learned_recon_game(energy: u16) -> GameState {
        let mut rules = rules_with_reconnaissance(ProgressionRules {
            starting_skill_points: 9,
            skill_points_per_level: 0,
            ..ProgressionRules::default()
        });
        rules.player_starting_energy = energy;
        rules.player_field_of_view.radius = 4;
        let mut game = GameState::new_with_rules(
            parse_map("#########\n#.......#\n#.......#\n#########"),
            GridPos::new(1, 1),
            7,
            rules,
        )
        .unwrap();
        game.player_progression
            .award(&ExperienceAward::repeatable(70), &game.rules.progression);
        assert_eq!(game.player_progression.level(), 5);
        for technique in [
            "core:rec_01",
            "core:rec_02",
            "core:rec_09",
            "core:rec_04",
            "core:rec_05",
        ] {
            assert_eq!(
                game.process_player_command(GameCommand::LearnTechnique {
                    technique: technique.parse().unwrap(),
                }),
                CommandOutcome::AppliedWithoutTime
            );
        }
        assert_eq!(game.player_progression().unspent_skill_points(), 0);
        assert_eq!(game.player_energy().available(), energy);
        assert_eq!(game.turn(), 0);
        game.drain_events();
        game
    }

    fn multiple_analysis_command(targets: Vec<EntityId>) -> GameCommand {
        GameCommand::UseTechnique {
            technique: "core:rec_09".parse().unwrap(),
            targets,
            weapon_slot: None,
        }
    }

    #[test]
    fn complete_recon_progression_executes_multi_analysis_with_the_same_individual_results() {
        let mut game = learned_recon_game(100);
        let targets: Vec<_> = (2..=4)
            .map(|x| {
                game.spawn_actor(
                    build_actor(GridPos::new(x, 1), x as u16 * 3).with_resistances(
                        ResistanceProfile::default().with(DamageType::Thermal, x as i16 * 10),
                    ),
                )
                .unwrap()
            })
            .collect();
        game.drain_events();
        let rng = game.rng_state();
        assert_eq!(
            game.process_player_command(multiple_analysis_command(targets.clone())),
            CommandOutcome::Applied
        );
        assert_eq!(game.turn(), 1);
        assert_eq!(game.player_energy().available(), 98);
        assert_eq!(game.rng_state(), rng);
        let multi_events: Vec<_> = game
            .drain_events()
            .into_iter()
            .filter(|event| matches!(event, GameEvent::TargetAnalyzed { .. }))
            .collect();
        assert_eq!(multi_events.len(), 3);
        let mut single_events = Vec::new();
        for target in targets {
            assert_eq!(
                game.process_player_command(GameCommand::UseTechnique {
                    technique: "core:rec_01".parse().unwrap(),
                    targets: vec![target],
                    weapon_slot: None,
                }),
                CommandOutcome::Applied
            );
            single_events.extend(
                game.drain_events()
                    .into_iter()
                    .filter(|event| matches!(event, GameEvent::TargetAnalyzed { .. })),
            );
        }
        assert_eq!(single_events, multi_events);
        assert_eq!(game.turn(), 4);
        assert_eq!(game.player_energy().available(), 98);
    }

    #[test]
    fn invalid_multi_analysis_is_atomic_even_when_only_the_last_target_is_hidden() {
        let mut game = learned_recon_game(100);
        let visible = game
            .spawn_actor(build_actor(GridPos::new(2, 1), 12))
            .unwrap();
        let second = game
            .spawn_actor(build_actor(GridPos::new(3, 1), 13))
            .unwrap();
        let third = game
            .spawn_actor(build_actor(GridPos::new(4, 1), 14))
            .unwrap();
        let hidden = game
            .spawn_actor(build_actor(GridPos::new(7, 1), 15))
            .unwrap();
        game.drain_events();
        let before = (
            game.turn(),
            game.rng_state(),
            game.player_energy(),
            game.export_player_progression().unwrap(),
        );
        for (targets, error) in [
            (vec![], CommandRejection::TechniqueMissingTarget),
            (
                vec![visible, visible],
                CommandRejection::TechniqueDuplicateTarget(visible),
            ),
            (
                vec![visible, second, third, hidden],
                CommandRejection::TechniqueTooManyTargets {
                    maximum: 3,
                    actual: 4,
                },
            ),
            (
                vec![visible, hidden],
                CommandRejection::TechniqueTargetNotVisible(hidden),
            ),
        ] {
            assert_eq!(
                game.process_player_command(multiple_analysis_command(targets)),
                CommandOutcome::Rejected(error)
            );
            assert!(game.events().is_empty());
            assert_eq!(
                (
                    game.turn(),
                    game.rng_state(),
                    game.player_energy(),
                    game.export_player_progression().unwrap()
                ),
                before
            );
        }
    }

    #[test]
    fn modded_analysis_range_is_inherited_by_execution_and_client_candidates() {
        let mut game = learned_recon_game(100);
        let mut catalog = SkillCatalog::default();
        for (_, discipline) in game.rules.skills.disciplines() {
            catalog.register_discipline(discipline.clone()).unwrap();
        }
        for (id, definition) in game.rules.skills.techniques() {
            let definition = match id.as_str() {
                "core:rec_01" => definition
                    .clone()
                    .with_action(TechniqueAction::AnalyzeTarget { range: 2 })
                    .unwrap(),
                "core:rec_09" => definition
                    .clone()
                    .with_action(TechniqueAction::AnalyzeMultipleTargets {
                        maximum_targets: 2,
                        energy_cost: 7,
                    })
                    .unwrap(),
                _ => definition.clone(),
            };
            catalog.register_technique(definition).unwrap();
        }
        catalog
            .validate_runtime(
                &game.rules.enabled_system_features,
                &game.rules.skill_progression,
            )
            .unwrap();
        game.rules.skills = catalog;
        let targets: Vec<_> = (2..=4)
            .map(|x| {
                game.spawn_actor(build_actor(GridPos::new(x, 1), 12))
                    .unwrap()
            })
            .collect();
        let technique = "core:rec_09".parse().unwrap();
        assert!(game.player_visibility().is_visible(GridPos::new(4, 1)));
        assert_eq!(game.player_technique_targets(&technique), targets[..2]);
        game.drain_events();
        assert_eq!(
            game.process_player_command(multiple_analysis_command(vec![targets[0], targets[2]])),
            CommandOutcome::Rejected(CommandRejection::TechniqueTargetOutOfRange(targets[2]))
        );
        assert_eq!(game.turn(), 0);
        assert_eq!(game.player_energy().available(), 100);
        assert!(game.events().is_empty());
        assert_eq!(
            game.process_player_command(multiple_analysis_command(targets[..2].to_vec())),
            CommandOutcome::Applied
        );
        assert_eq!(game.turn(), 1);
        assert_eq!(game.player_energy().available(), 93);
    }

    #[test]
    fn empty_energy_blocks_only_costly_actions_and_progression_restore_cannot_refill_it() {
        let mut game = learned_recon_game(2);
        let target = game
            .spawn_actor(build_actor(GridPos::new(2, 1), 30))
            .unwrap();
        let saved = game.export_player_progression().unwrap();
        assert_eq!(
            game.process_player_command(multiple_analysis_command(vec![target])),
            CommandOutcome::Applied
        );
        assert_eq!(game.player_energy().available(), 0);
        game.restore_player_progression(&saved).unwrap();
        game.drain_events();
        assert_eq!(
            game.process_player_command(multiple_analysis_command(vec![target])),
            CommandOutcome::Rejected(CommandRejection::InsufficientEnergy {
                required: 2,
                available: 0
            })
        );
        assert_eq!(game.turn(), 1);
        assert!(game.events().is_empty());
        for command in [
            GameCommand::Wait,
            GameCommand::Attack { slot: 0, target },
            GameCommand::Move(Direction::South),
        ] {
            assert_eq!(
                game.process_player_command(command),
                CommandOutcome::Applied
            );
            assert_eq!(game.player_energy().available(), 0);
        }
    }

    #[test]
    fn wall_examination_is_bound_to_rec04_and_other_learned_actions_are_executable() {
        let mut game = learned_recon_game(0);
        let target = game
            .spawn_actor(
                build_actor(GridPos::new(2, 1), 12)
                    .with_attack(AttackProfile::melee(DamageType::Kinetic, 3)),
            )
            .unwrap();
        game.drain_events();
        assert_eq!(
            game.process_player_command(GameCommand::UseTechnique {
                technique: "core:rec_04".parse().unwrap(),
                targets: vec![],
                weapon_slot: None,
            }),
            CommandOutcome::Applied
        );
        let events = game.drain_events();
        let tiles = events
            .iter()
            .find_map(|event| match event {
                GameEvent::TerrainAnalyzed { tiles, .. } => Some(tiles),
                _ => None,
            })
            .unwrap();
        assert!(!tiles.is_empty() && tiles.len() <= 3);
        for (index, tile) in tiles.iter().enumerate() {
            assert!(game.player_visibility().is_visible(tile.position));
            assert!(tile.blocks_movement && tile.blocks_vision);
            if index > 0 {
                assert!(
                    tiles[..index]
                        .iter()
                        .any(|other| other.position.cardinal_neighbors().contains(&tile.position))
                );
            }
        }
        assert_eq!(
            game.process_player_command(GameCommand::UseTechnique {
                technique: "core:rec_05".parse().unwrap(),
                targets: vec![target],
                weapon_slot: None,
            }),
            CommandOutcome::Applied
        );
        assert!(game.events().iter().any(
            |event| matches!(event, GameEvent::ThreatAnalyzed { attacks, .. } if attacks.len() == 1)
        ));
    }

    #[test]
    fn meticulous_inspection_discovers_only_real_detectable_devices_after_preparation() {
        let mut game = game_with_complete_reconnaissance(&["rec_01", "rec_03"]);
        let payload = || {
            vec![ScheduledExplosivePayload::new(
                0,
                crate::explosive::ExplosivePayload::new(
                    crate::explosive::ExplosiveFootprint::Radial(RadialDamageEffect {
                        maximum_cost: 1,
                        neighbor_mode: crate::world::NeighborMode::CardinalAndDiagonal,
                        propagation_policy:
                            crate::world::TerrainPropagationPolicy::blocked_by_walls(1),
                        damage: DamagePacket::new(5, DamageType::Explosive, 0),
                        falloff: crate::effects::DamageFalloff::None,
                    }),
                ),
            )]
        };
        let visible = game
            .explosive_devices
            .deploy(
                "core:proximity_mine".parse().unwrap(),
                None,
                GridPos::new(3, 1),
                Direction::North,
                ExplosiveActivation::Remote {
                    maximum_link_range: 6,
                },
                false,
                payload(),
            )
            .unwrap();
        game.explosive_devices
            .set_optical_concealment(visible, 20)
            .unwrap();
        let too_well_hidden = game
            .explosive_devices
            .deploy(
                "core:proximity_mine".parse().unwrap(),
                None,
                GridPos::new(3, 2),
                Direction::North,
                ExplosiveActivation::Remote {
                    maximum_link_range: 6,
                },
                false,
                payload(),
            )
            .unwrap();
        game.explosive_devices
            .set_optical_concealment(too_well_hidden, 30)
            .unwrap();
        let command = || GameCommand::UseTechnique {
            technique: "core:rec_03".parse().unwrap(),
            targets: Vec::new(),
            weapon_slot: None,
        };

        assert_eq!(
            game.process_player_command(command()),
            CommandOutcome::Applied
        );
        assert!(
            !game
                .explosive_devices()
                .get(visible)
                .unwrap()
                .is_identified()
        );
        assert_eq!(
            game.process_player_command(command()),
            CommandOutcome::Applied
        );
        assert!(
            game.explosive_devices()
                .get(visible)
                .unwrap()
                .is_identified()
        );
        assert!(
            !game
                .explosive_devices()
                .get(too_well_hidden)
                .unwrap()
                .is_identified()
        );
        assert!(game.events().contains(&GameEvent::SecretsInspected {
            observer: game.player,
            discovered_explosives: vec![visible],
        }));
    }

    #[test]
    fn energy_diagnostic_reads_a_real_drone_reserve_and_rejects_an_actor_without_one() {
        let mut game = game_with_complete_reconnaissance(&["rec_01", "rec_03", "rec_05", "rec_08"]);
        let drone = spawn_test_player_drone(&mut game, GridPos::new(3, 1));
        game.actors
            .get_mut(drone)
            .unwrap()
            .drone_mut()
            .unwrap()
            .spend_energy(13)
            .unwrap();
        let ordinary = game
            .spawn_actor(Actor::new(GridPos::new(2, 2), 20).unwrap())
            .unwrap();
        let technique: TechniqueId = "core:rec_08".parse().unwrap();
        assert_eq!(game.player_technique_targets(&technique), vec![drone]);
        game.drain_events();

        assert_eq!(
            game.process_player_command(GameCommand::UseTechnique {
                technique: technique.clone(),
                targets: vec![drone],
                weapon_slot: None,
            }),
            CommandOutcome::Applied
        );
        assert_eq!(game.player_energy().available(), 98);
        assert!(game.events().contains(&GameEvent::EnergyAnalyzed {
            observer: game.player,
            target: drone,
            state: EnergyAnalysis {
                analysis_score: 70,
                energy_available: Some(17),
                energy_capacity: Some(30),
                heat: None,
                bandwidth_occupied: None,
                bandwidth_capacity: None,
            },
        }));

        game.drain_events();
        let before = (game.turn(), game.player_energy());
        assert_eq!(
            game.process_player_command(GameCommand::UseTechnique {
                technique,
                targets: vec![ordinary],
                weapon_slot: None,
            }),
            CommandOutcome::Rejected(CommandRejection::TechniqueTargetHasNoEnergyState(ordinary))
        );
        assert_eq!((game.turn(), game.player_energy()), before);
        assert!(game.events().is_empty());
    }

    #[test]
    fn turn_start_status_resolves_before_the_affected_ai_can_act() {
        let (rules, status) = triggered_damage_status_rules(StatusTrigger::TurnStart, 2);
        let mut game = GameState::new_with_rules(
            parse_map("#######\n#.....#\n#######"),
            GridPos::new(1, 1),
            1,
            rules,
        )
        .unwrap();
        let enemy = game
            .spawn_actor(build_actor(GridPos::new(4, 1), 10).with_ai(AiProfile::hunter(8, 0)))
            .unwrap();
        game.actors
            .get_mut(enemy)
            .unwrap()
            .apply_status(&status, 1, None);
        game.drain_events();

        assert_eq!(
            game.process_player_command(GameCommand::Wait),
            CommandOutcome::Applied
        );

        assert_eq!(game.actors.get(enemy).map(Actor::integrity), Some(8));
        assert_eq!(
            game.actors.get(enemy).map(Actor::position),
            Some(GridPos::new(3, 1))
        );
        let trigger_index = game
            .events()
            .iter()
            .position(|event| {
                matches!(
                    event,
                    GameEvent::StatusTriggered {
                        target,
                        trigger: StatusTrigger::TurnStart,
                        ..
                    } if *target == enemy
                )
            })
            .unwrap();
        let movement_index = game
            .events()
            .iter()
            .position(
                |event| matches!(event, GameEvent::EntityMoved { entity, .. } if *entity == enemy),
            )
            .unwrap();
        assert!(trigger_index < movement_index);
    }

    #[test]
    fn movement_status_triggers_once_only_after_a_completed_move() {
        let (rules, status) = triggered_damage_status_rules(StatusTrigger::Movement, 2);
        let mut game = GameState::new_with_rules(
            parse_map("#####\n#...#\n#####"),
            GridPos::new(1, 1),
            1,
            rules,
        )
        .unwrap();
        let player = game.player_id();
        game.actors
            .get_mut(player)
            .unwrap()
            .apply_status(&status, 1, None);
        let initial_integrity = game.actors.get(player).unwrap().integrity();
        game.drain_events();

        assert!(matches!(
            game.process_player_command(GameCommand::Move(Direction::North)),
            CommandOutcome::Rejected(CommandRejection::BlockedByTerrain(_))
        ));
        assert_eq!(
            game.actors.get(player).map(Actor::integrity),
            Some(initial_integrity)
        );
        assert!(!game.events().iter().any(|event| matches!(
            event,
            GameEvent::StatusTriggered {
                target,
                trigger: StatusTrigger::Movement,
                ..
            } if *target == player
        )));

        assert_eq!(
            game.process_player_command(GameCommand::Move(Direction::East)),
            CommandOutcome::Applied
        );
        assert_eq!(game.player_position(), Some(GridPos::new(2, 1)));
        assert_eq!(
            game.actors.get(player).map(Actor::integrity),
            Some(initial_integrity - 2)
        );
        assert_eq!(
            game.events()
                .iter()
                .filter(|event| matches!(
                    event,
                    GameEvent::StatusTriggered {
                        target,
                        trigger: StatusTrigger::Movement,
                        ..
                    } if *target == player
                ))
                .count(),
            1
        );
    }

